import os
import unicodedata
from flask import Flask, request, jsonify, abort
from werkzeug.utils import secure_filename
import hashlib
import hmac
import re

app = Flask(__name__)

BASE_DIR = os.path.abspath('/srv/documents')
SECRET_KEY = os.environ.get('DOC_SECRET', 'production-key-set-via-env')

def verify_token(token, resource_path):
    """HMAC-based access token verification"""
    if not token or not resource_path:
        return False
    expected = hmac.new(
        SECRET_KEY.encode('utf-8'),
        resource_path.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(token, expected)

def is_safe_path(base, requested_path):
    """Check if the requested path is within the base directory.
    Prevents directory traversal attacks."""
    # Reject obvious traversal patterns
    if '..' in requested_path and '/' in requested_path:
        return False
    if '..' in requested_path and '\\' in requested_path:
        return False
    # Check for null bytes
    if '\x00' in requested_path:
        return False
    # Reject absolute paths
    if requested_path.startswith('/') or requested_path.startswith('\\'):
        return False
    # Reject backslash usage
    if '\\' in requested_path:
        return False
    # Additional check: no path separator after ..
    if re.search(r'\.\.[/\\]', requested_path):
        return False
    return True

def normalize_document_name(name):
    """Normalize unicode characters in document names for consistent storage lookup.
    Uses NFKC normalization for compatibility equivalence."""
    return unicodedata.normalize('NFKC', name)

def sanitize_for_logging(value):
    """Remove control characters from values before logging"""
    return ''.join(c if ord(c) >= 32 and ord(c) != 127 else '_' for c in value)

@app.route('/api/documents/<path:doc_path>', methods=['GET'])
def get_document(doc_path):
    """Retrieve a document by path. Requires valid access token."""
    token = request.headers.get('X-Access-Token', '')
    client_ip = request.remote_addr

    # Log access attempt
    safe_path_log = sanitize_for_logging(doc_path)
    app.logger.info(f"Document access attempt: path={safe_path_log} ip={client_ip}")

    # Step 1: Validate path safety BEFORE any filesystem operations
    if not is_safe_path(BASE_DIR, doc_path):
        app.logger.warning(f"Path traversal blocked: {safe_path_log}")
        abort(403)

    # Step 2: Normalize the document name for consistent lookup
    # This handles cases where users might use different Unicode representations
    normalized_path = normalize_document_name(doc_path)

    # Step 3: Verify access token against the normalized path
    if not verify_token(token, normalized_path):
        abort(401)

    # Step 4: Construct full path and serve
    full_path = os.path.normpath(os.path.join(BASE_DIR, normalized_path))

    # Final safety check - ensure we're still within BASE_DIR
    if not full_path.startswith(BASE_DIR):
        abort(403)

    if not os.path.isfile(full_path):
        abort(404)

    with open(full_path, 'r') as f:
        content = f.read()

    return jsonify({'content': content, 'path': normalized_path})

@app.route('/api/documents', methods=['POST'])
def upload_document():
    """Upload a new document."""
    token = request.headers.get('X-Access-Token', '')
    if not verify_token(token, 'upload'):
        abort(401)

    if 'file' not in request.files:
        abort(400)

    file = request.files['file']
    filename = secure_filename(file.filename)
    if not filename:
        abort(400)

    dest = os.path.join(BASE_DIR, filename)
    file.save(dest)
    return jsonify({'status': 'ok', 'filename': filename}), 201

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080, debug=False)
